<?php
namespace App\Application\Compliance;use App\Application\Audit\AuditWriter;use App\Application\Events\OutboxWriter;use App\Models\{ComplianceCase,User};use Illuminate\Support\{Facades\DB,Str};use Illuminate\Validation\ValidationException;
final class ComplianceCaseService{public function __construct(private AuditWriter$a,private OutboxWriter$o){}public function open(string$tenant,array$d,User$u):ComplianceCase{$hash=hash('sha256',json_encode($d,JSON_THROW_ON_ERROR));if($x=ComplianceCase::where(['tenant_id'=>$tenant,'idempotency_key'=>$d['idempotency_key']])->first()){if(!hash_equals($x->payload_hash,$hash))throw ValidationException::withMessages(['idempotency_key'=>__('wave9.idempotency_conflict')]);return$x;}return DB::transaction(function()use($tenant,$d,$u,$hash){$x=ComplianceCase::create([...$d,'tenant_id'=>$tenant,'case_number'=>'CMP-'.now()->format('Ym').'-'.strtoupper(Str::random(8)),'status'=>'OPEN','payload_hash'=>$hash,'opened_by'=>$u->id]);$this->event($x,null,'OPEN','CASE_OPENED',$u);$this->a->record('compliance.case.opened','compliance_case',$x->id,[]);$this->o->record('compliance.case.opened','compliance_case',$x->id,['case_id'=>$x->id]);return$x;});}public function transition(ComplianceCase$x,string$to,string$reason,array$findings,User$u):ComplianceCase{return DB::transaction(function()use($x,$to,$reason,$findings,$u){$x=ComplianceCase::whereKey($x->id)->lockForUpdate()->firstOrFail();$allowed=['OPEN'=>['UNDER_REVIEW'],'UNDER_REVIEW'=>['REMEDIATION','CLOSED'],'REMEDIATION'=>['UNDER_REVIEW','CLOSED'],'CLOSED'=>['REOPENED'],'REOPENED'=>['UNDER_REVIEW']];if(!in_array($to,$allowed[$x->status]??[],true)||($to==='CLOSED'&&$x->opened_by===$u->id))throw ValidationException::withMessages(['status'=>__('wave9.transition_invalid')]);$from=$x->status;$x->update(['status'=>$to,'findings'=>$findings,'closed_at'=>$to==='CLOSED'?now():null,'closed_by'=>$to==='CLOSED'?$u->id:null,'closure_code'=>$to==='CLOSED'?$reason:null,'version'=>$x->version+1]);$this->event($x,$from,$to,$reason,$u);$this->a->record('compliance.case.transitioned','compliance_case',$x->id,['from'=>$from,'to'=>$to],$reason);return$x->refresh();});}private function event(ComplianceCase$x,?string$f,string$t,string$r,User$u):void{DB::table('compliance_case_events')->insert(['id'=>(string)Str::uuid(),'compliance_case_id'=>$x->id,'from_status'=>$f,'to_status'=>$t,'reason_code'=>$r,'actor_id'=>$u->id,'metadata'=>'{}','occurred_at'=>now()]);}}
